def most_frequent_value_key(mapping):
    if not mapping:
        return None

    value_counts = {}
    for key, value in mapping.items():
        if value in value_counts:
            value_counts[value] += 1
        else:
            value_counts[value] = 1

    max_count = max(value_counts.values())
    for key, count in mapping.items():
        if count == max_count:
            return key

