def first_non_repeating(text):
    if not text:
        return None

    char_count = {}

    # Count occurrences of each character
    for char in text:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a count of 1
    for char in text:
        if char_count[char] == 1:
            return char

    # If no non-repeating character is found, return None
    return None

